]

def get_component_size(grid, start_r, start_c):
    visited = set()
    size = 0
    stack = [(start_r, start_c)]
    while stack:
        r, c = stack.pop()
        key = (r, c)
        if key in visited:
            continue
        visited.add(key)
        size += 1
        # 8-connectivity
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == 2 and key not in visited:
                        stack.append((nr, nc))
    return size

# Find max component size and mark all cells belonging to components with that size
max_size = 0
comp_sizes = []
for r in range(7):
    for c in range(24):
        if grid[r][c] == 2:
            size = get_component_size(grid, r, c)
            comp_sizes.append(size)
            if size > max_size:
                max_size = size
print(f"Max component size: {max_size}")

# Mark all cells that belong to max-size component
hyp_max_comp = [[0]*24 for _ in range(7)]
seen_in_max = set()
for r in range(7):
    for c in range(24):
        if grid[r][c] == 2 and (r,c) not in seen_in_max:
            size = get_component_size(grid, r, c)
            if size == max_size:
                # Mark this entire component
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in seen_in_max:
                        continue
                    seen_in_max.add((cr, cc))
                    hyp_max_comp[cr][cc] = 2
                    # 8-connectivity
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < 7 and 0 <= nc < 24:
                                if grid[nr][nc] == 2 and (nr, nc) not in seen_in_max:
                                    stack.append((nr, nc))

