def has_orthogonal_neighbor(grid, r, c):
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 7 and 0 <= nc < 24 and grid[nr][nc] == 2:
                # Check if it's orthogonal (not diagonal)
                if abs(dr) + abs(dc) == 1:
                    return True
    return False

