def has_diagonal_pair_neighbor(grid, r, c):
    # Check if any of the 8 neighboring cells form a diagonal pair with another neighbor
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 7 and 0 <= nc < 24 and grid[nr][nc] == 2:
                neighbors.append((nr, nc))

    # Check if any two neighbors have diagonal relationship
    for i in range(len(neighbors)):
        for j in range(i+1, len(neighbors)):
            dr1, dc1 = neighbors[i][0] - r, neighbors[i][1] - c
            dr2, dc2 = neighbors[j][0] - r, neighbors[j][1] - c
            # Diagonal means |dr1*dc2 - dr2*dc1| > 0 (cross product)
            if abs(dr1 * dc2 - dr2 * dc1) > 0:
                return True
    return False

