def get_diag_component_size(grid, start_r, start_c):
    visited = set()
    size = 0
    stack = [(start_r, start_c)]
    while stack:
        r, c = stack.pop()
        key = (r, c)
        if key in visited:
            continue
        visited.add(key)
        size += 1
        # Diagonal-only connectivity (4 diagonal directions)
        for dr in [-1, 1]:
            for dc in [-1, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 7 and 0 <= nc < 24:
                    if grid[nr][nc] == 2 and (nr, nc) not in visited:
                        stack.append((nr, nc))
    return size

